    nodes.forEach((n) => { x0 = Math.min(x0, n.x); x1 = Math.max(x1, n.x); y0 = Math.min(y0, n.y); y1 = Math.max(y1, n.y); z0 = Math.min(z0, n.z); z1 = Math.max(z1, n.z); });
