      const r = sizeOf(n) * (0.4 + 0.6 * n.g);
      const lay = !n.on ? 3 : n.d > field.r * 0.35 ? 0 : n.d > -field.r * 0.35 ? 1 : 2;
      if (r < 1.3) P[lay].rect(n.sx - r, n.sy - r, r * 2, r * 2);
