    c.globalAlpha = dark ? 0.5 : 0.48; c.fill(P[0]);
    c.globalAlpha = dark ? 0.72 : 0.72; c.fill(P[1]);
    c.globalAlpha = 0.94; c.fill(P[2]);
    // the hubs: a perfumer a ring, as image 6's busiest
